import com.luci.pianoroom.VideoModePolicy;
public final class VideoModePolicyTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args){
  check(VideoModePolicy.frameRate(60,16666667,8333333,60,60),"60 fps when both streams support it");check(!VideoModePolicy.frameRate(60,33333333,16666667,30,60),"video limits preview despite AE range");check(!VideoModePolicy.frameRate(60,16666667,33333333,60,60),"preview limits video");check(!VideoModePolicy.frameRate(30,33333333,16666667,30,60),"do not record 30 while capture runs at 60");check(!VideoModePolicy.frameRate(120,8333333,8333333,120,120),"constrained high speed is a separate pipeline");check(VideoModePolicy.frameRate(30,0,0,15,30),"reported variable AE mode remains supported");
  int[] back={90,0,270,180},front={270,0,90,180};for(int i=0;i<4;i++){check(VideoModePolicy.orientation(90,i*90,false)==back[i],"back orientation");check(VideoModePolicy.orientation(270,i*90,true)==front[i],"front orientation");check(VideoModePolicy.relativeRotation(90,i*90,false)%180==VideoModePolicy.orientation(90,i*90,false)%180,"preview/video aspect consistency");}
  for(int sensor:new int[]{0,90,180,270})for(int display:new int[]{0,90,180,270}){int w=display%180==0?360:640,h=display%180==0?640:360;float[] scale=VideoModePolicy.previewScale(w,h,1280,720,sensor,display);float nw=sensor%180==0?1280:720,nh=sensor%180==0?720:1280;check(Math.abs(w*scale[0]/nw-h*scale[1]/nh)<1e-5,"preview does not stretch pixels");float boundW=display%180==0?w*scale[0]:h*scale[1],boundH=display%180==0?h*scale[1]:w*scale[0];check(boundW>=w-.01&&boundH>=h-.01,"preview covers viewport in every orientation");}
  check(VideoModePolicy.bitrate(3840,2160,60,1_000_000,30_000_000)==30_000_000,"respect codec bitrate cap");check(VideoModePolicy.bitrate(1920,1080,30,1_000_000,50_000_000)>7_000_000,"scale quality for resolution and fps");check(VideoModePolicy.label(3840,2160,60,false).contains("4K")&&VideoModePolicy.label(1920,1080,30,false).contains("até 30"),"clearly label variable fps");System.out.println("PASS: dual-stream FPS limits, codec bitrate bounds, all front/back orientations, variable FPS labels.");
 }
}
